# files that only the Django version used
OBSOLETE = ['lib/backend.js']

root = os.getcwd()
if not (os.path.isdir(os.path.join(root, 'app')) and os.path.isdir(os.path.join(root, 'lib'))):
    sys.exit('ERROR: run this inside the exit-exam-starter folder (the one with "app" and "lib").')

for rel, b64 in FILES.items():
    target = os.path.join(root, *rel.split('/'))
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'wb') as fh:
        fh.write(base64.b64decode(b64))
    print('restored ', rel)

for rel in OBSOLETE:
    target = os.path.join(root, *rel.split('/'))
    if os.path.exists(target):
        os.remove(target)
        print('removed  ', rel)

print()
print('Done! Now:')
print('  1. Open .env.local and make sure it has your 3 Supabase lines:')
print('       NEXT_PUBLIC_SUPABASE_URL=...')
print('       NEXT_PUBLIC_SUPABASE_ANON_KEY=...')
print('       SUPABASE_SERVICE_ROLE_KEY=...')
print('     (the line NEXT_PUBLIC_API_URL=... is no longer needed; you can delete it)')
print('  2. Restart the website: Ctrl+C, then  npm run dev')
